/**
 * Every page of a list or view: `for await (const page of paginate(client.todos.list, { limit: 50 }))`.
 * Follows `pagination.nextCursor`; when the cursor is null (sorting by a
 * column masked for the caller) it continues by `offset` instead.
 */
export async function* paginate<Params extends ListParams<any>, Page extends Qb.Page<unknown>>(
  list: (params?: Params) => Promise<Page>,
  params?: Params,
): AsyncGenerator<Page, void, undefined> {
  let next = { ...params } as Params;
  for (;;) {
    const page = await list(next);
    yield page;
    const { hasMore, nextCursor } = page.pagination;
    if (!hasMore || page.data.length === 0) return;
    next = nextCursor
      ? { ...next, startingAfter: nextCursor, endingBefore: undefined, offset: undefined }
      : { ...next, startingAfter: undefined, offset: (next.offset ?? 0) + page.data.length };
  }
}

type Query = Record<string, unknown> | undefined;

/** Collection/record reads: every list value is comma-joined (`?status.in=a,b`, `?fields=a,b`). */
function listQuery(params?: ListParams<any> | GetParams<any>): Query {
  if (!params) return undefined;
  const p = params as ListParams<any>;
  const join = (value: unknown) => (Array.isArray(value) ? value.join(",") : value);
  const out: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(p.filter ?? {})) out[key] = join(value);
  out.limit = p.limit;
  out.offset = p.offset;
  out.sort = p.sort;
  out.search = p.search;
  out.total = p.total;
  out.fields = join(p.fields);
  out.include = join(p.include);
  out.starting_after = p.startingAfter;
  out.ending_before = p.endingBefore;
  return out;
}

function fill(path: string, params: Record<string, unknown>): string {
  // `{name}` (resource routes) or `:name` (authored standalone paths).
  return path.replace(/\{([^}]+)\}|:([A-Za-z_$][A-Za-z0-9_$]*)/g, (_, braced?: string, colon?: string) => {
    const name = (braced ?? colon)!;
    const value = params[name];
    if (value === undefined || value === null) throw new Error(`Missing path parameter "${name}"`);
    return encodeURIComponent(String(value));
  });
}

